"""generates libsrc/th_geom.hum.imo: the geometry packages (incidence, euclid, hilbert, hyperbolic, elliptic) from the lists below"""
def L(*xs): return '\\n'.join(x.replace('\\', '\\\\') for x in xs)
def theory(name, req, conf, default, sig, rules, axioms, theorems, doc):
    q = lambda lst: '[' + ', '.join('"%s"' % x for x in lst) + ']'
    v = 'th' + name
    out = [f'{v}sig in List(String) := lines("{sig}")', f'{v}rules in List(String) := lines("{rules}")', f'{v}axioms in List(String) := lines("{axioms}")',
           f'{v}theorems in List(String) := lines("{theorems}")', f'{v}doc in String := "{doc}"',
           f'{v} in Theory := mktheory("{name}", {q(req)}, {q(conf)}, {"true" if default else "false"}, {v}sig, {v}rules, [], {v}axioms, {v}theorems, {v}doc)']
    return '\n'.join(out)
parts = ['-- th_geom.hum.imo -- the geometry packages: incidence, euclid, hilbert, hyperbolic, elliptic (generated by libsrc/gen/th_geom.py; human notation; lib/th_geom.imo is its translation).',
         '-- Points are terms: variables, or pt(x, y) with coordinates; px and py are the coordinates.  The predicates are rewritten into polynomial equations in the coordinates, which the arithmetic of the package arith decides.',
         '-- euclid, hyperbolic and elliptic give the same words different meanings (rightangle, cong) and exclude one another: the parallel postulate, and what replaces it.']
# ---------------------------------------------------------------------------------------------------------------- incidence
parts.append(theory('incidence', ['arith'], [], False,
    L('fn 0 pt pt', 'fn 0 px px', 'fn 0 py py', 'fn 0 cross cross', 'fn 0 collinear collinear', 'fn 0 same same', 'fn 0 lna lna', 'fn 0 lnb lnb', 'fn 0 lnc lnc'),
    L('px(pt(x, y)) ==> x', 'py(pt(x, y)) ==> y',
      'cross(A, B, C) ==> (px(B) - px(A)) * (py(C) - py(A)) - (py(B) - py(A)) * (px(C) - px(A))',
      'collinear(A, B, C) ==> cross(A, B, C) = 0',
      'same(P, Q) ==> px(P) = px(Q) && py(P) = py(Q)',
      'lna(A, B) ==> py(A) - py(B)', 'lnb(A, B) ==> px(B) - px(A)', 'lnc(A, B) ==> px(A) * py(B) - px(B) * py(A)'),
    L('points are pairs (x, y) of real numbers and a line is the set of the solutions of a x + b y + c = 0 with (a, b) different from (0, 0) (the coordinate model; the axioms below hold in it)',
      'I.1 for two different points A, B there is a line that contains both',
      'I.2 for two different points A, B there is no more than one line that contains both',
      'I.3 every line contains at least two points; there are three points that do not lie on one line',
      'three points A, B, C are collinear exactly when cross(A, B, C) = (xB - xA)(yC - yA) - (yB - yA)(xC - xA) vanishes (twice the signed area of the triangle)',
      'the line through A and B has the coordinates (a, b, c) = (yA - yB, xB - xA, xA yB - xB yA): the functions lna, lnb, lnc',
      'same(P, Q) says that two points have the same coordinates'),
    L('collinear(A, A, B)', 'collinear(A, B, A)', 'collinear(A, B, B)', 'collinear(A, B, C) <=> collinear(B, A, C)', 'collinear(A, B, C) <=> collinear(A, C, B)', 'collinear(A, B, C) <=> collinear(B, C, A)',
      'cross(A, B, C) = -cross(B, A, C)', 'cross(A, B, C) = cross(B, C, A)', 'cross(A, B, C) = cross(O, A, B) + cross(O, B, C) + cross(O, C, A)', 'cross(A, B, A) = 0',
      'collinear(pt(0, 0), pt(1, 1), pt(2, 2))', '¬collinear(pt(0, 0), pt(1, 0), pt(0, 1))', 'collinear(pt(0, 0), pt(1, 2), pt(x, 2 * x))', 'collinear(pt(0, 1), pt(1, 3), pt(x, 2 * x + 1))',
      'cross(pt(0, 0), pt(1, 0), pt(0, 1)) = 1', 'same(A, A)', 'same(A, B) <=> same(B, A)', '(same(A, B) && same(B, C)) => same(A, C)',
      'lna(A, B) = -lna(B, A)', 'lnc(A, B) = -lnc(B, A)'),
    'points, collinearity and lines in coordinates: the incidence geometry of the plane that euclid, hyperbolic and elliptic share'))
# ---------------------------------------------------------------------------------------------------------------- euclid
parts.append(theory('euclid', ['incidence'], ['hyperbolic', 'elliptic'], False,
    L('fn 0 midpoint midpoint C', 'fn 0 centroid centroid C', 'fn 0 fourth fourth', 'fn 0 reflect reflect', 'fn 0 rot rot', 'fn 0 dist2 dist2 C', 'fn 0 dot dot', 'fn 0 perp perp', 'fn 0 par par',
      'fn 0 cong cong', 'fn 0 oncircle oncircle', 'fn 0 between between', 'fn 0 rightangle rightangle'),
    L('px(midpoint(A, B)) ==> (px(A) + px(B)) / 2', 'py(midpoint(A, B)) ==> (py(A) + py(B)) / 2',
      'px(centroid(A, B, C)) ==> (px(A) + px(B) + px(C)) / 3', 'py(centroid(A, B, C)) ==> (py(A) + py(B) + py(C)) / 3',
      'px(fourth(A, B, C)) ==> px(A) - px(B) + px(C)', 'py(fourth(A, B, C)) ==> py(A) - py(B) + py(C)',
      'px(reflect(P, O)) ==> 2 * px(O) - px(P)', 'py(reflect(P, O)) ==> 2 * py(O) - py(P)',
      'px(rot(P, O)) ==> px(O) - (py(P) - py(O))', 'py(rot(P, O)) ==> py(O) + (px(P) - px(O))',
      'dist2(A, B) ==> (px(A) - px(B))^2 + (py(A) - py(B))^2',
      'dot(A, B, C) ==> (px(B) - px(A)) * (px(C) - px(A)) + (py(B) - py(A)) * (py(C) - py(A))',
      'perp(A, B, C, D) ==> lna(A, B) * lna(C, D) + lnb(A, B) * lnb(C, D) = 0',
      'par(A, B, C, D) ==> lna(A, B) * lnb(C, D) - lnb(A, B) * lna(C, D) = 0',
      'cong(A, B, C, D) ==> dist2(A, B) = dist2(C, D)',
      'oncircle(P, O, A) ==> dist2(O, P) = dist2(O, A)',
      'rightangle(A, B, C) ==> dot(B, A, C) = 0',
      'between(A, B, C) ==> collinear(A, B, C) && dot(B, A, C) < 0'),
    L('Euclid, Elements, Book I.  Common notions: 1 things equal to the same thing are equal to one another; 2 if equals are added to equals, the wholes are equal; 3 if equals are subtracted from equals, the remainders are equal; 4 things that coincide with one another are equal to one another; 5 the whole is greater than the part',
      'Postulate 1: to draw a straight line from any point to any point',
      'Postulate 2: to produce a finite straight line continuously in a straight line',
      'Postulate 3: to describe a circle with any centre and distance',
      'Postulate 4: all right angles are equal to one another',
      'Postulate 5 (the parallel postulate): if a straight line falling on two straight lines makes the interior angles on the same side less than two right angles, the two straight lines, if produced indefinitely, meet on that side',
      'Playfair: through a point outside a line there is exactly one line that does not meet it (equivalent to Postulate 5 in the presence of the other axioms)',
      'the model: the plane of the pairs (x, y) of reals with dist2(A, B) = (xA - xB)^2 + (yA - yB)^2; perp: the directions have the inner product 0; par: the directions have the cross product 0',
      'midpoint, centroid, fourth (the fourth vertex D = A - B + C of the parallelogram ABCD), reflect (the point reflection of P in O) and rot (the rotation of P by a right angle about O) are constructions with rational coordinates',
      'between(A, B, C): B lies strictly between A and C (collinear, and the inner product of A - B and C - B is negative)',
      'rightangle(A, B, C): the angle at B is a right angle (the inner product of A - B and C - B vanishes)'),
    L('collinear(A, midpoint(A, B), B)', '4 * dist2(A, midpoint(A, B)) = dist2(A, B)', 'dist2(A, midpoint(A, B)) = dist2(midpoint(A, B), B)', 'midpoint(A, B) = midpoint(B, A)', 'same(midpoint(A, A), A)',
      'dist2(A, B) = dist2(B, A)', 'dist2(A, A) = 0', 'dist2(A, B) >= 0', 'dist2(A, C) <= 2 * dist2(A, B) + 2 * dist2(B, C)',
      'perp(A, B, B, C) => dist2(A, C) = dist2(A, B) + dist2(B, C)', 'dist2(A, C) = dist2(A, B) + dist2(B, C) => perp(A, B, B, C)', 'rightangle(A, B, C) <=> perp(B, A, B, C)',
      'oncircle(C, midpoint(A, B), A) => rightangle(A, C, B)', 'rightangle(A, C, B) => oncircle(C, midpoint(A, B), A)',
      'par(midpoint(A, B), midpoint(A, C), B, C)', '4 * dist2(midpoint(A, B), midpoint(A, C)) = dist2(B, C)',
      'par(A, B, fourth(A, B, C), C)', 'par(B, C, A, fourth(A, B, C))', 'cong(A, B, fourth(A, B, C), C)', 'cong(B, C, A, fourth(A, B, C))', 'same(midpoint(A, C), midpoint(B, fourth(A, B, C)))',
      'dist2(A, C) + dist2(B, fourth(A, B, C)) = 2 * dist2(A, B) + 2 * dist2(B, C)',
      'same(fourth(midpoint(A, B), midpoint(B, C), midpoint(C, D)), midpoint(D, A))', 'par(midpoint(A, B), midpoint(B, C), A, C)',
      'collinear(A, midpoint(B, C), centroid(A, B, C))', 'cross(A, B, centroid(A, B, C)) = cross(A, B, C) / 3',
      'dist2(A, B) + dist2(A, C) = 2 * dist2(A, midpoint(B, C)) + dist2(B, C) / 2',
      'same(reflect(reflect(A, O), O), A)', 'cong(A, O, O, reflect(A, O))', 'same(midpoint(A, reflect(A, O)), O)', 'cong(O, P, O, rot(P, O))', 'rightangle(P, O, rot(P, O))',
      'perp(A, B, C, D) <=> perp(C, D, A, B)', 'perp(A, B, C, D) <=> perp(B, A, C, D)', 'par(A, B, C, D) <=> par(C, D, A, B)',
      '(dist2(pt(0, 0), A) = dist2(pt(0, 0), B) && dist2(pt(0, 0), B) = dist2(pt(0, 0), C)) => perp(A, pt(px(A) + px(B) + px(C), py(A) + py(B) + py(C)), B, C)',
      'dist2(A, B) > 0 => between(A, midpoint(A, B), B)',
      'perp(pt(0, 0), pt(1, 0), pt(0, 0), pt(0, 1))', 'cong(pt(0, 0), pt(3, 4), pt(1, 1), pt(6, 1))', 'dist2(pt(0, 0), pt(3, 4)) = 25', 'rightangle(pt(0, 0), pt(3, 0), pt(3, 4))',
      'dist2(pt(0, 0), pt(3, 4)) = dist2(pt(0, 0), pt(3, 0)) + dist2(pt(3, 0), pt(3, 4))',
      'rightangle(pt(3/4, 1/4), pt(1/2, 1/4), pt(1/2, 1/2)) && rightangle(pt(1/2, 1/4), pt(1/2, 1/2), pt(3/4, 1/2)) && rightangle(pt(1/2, 1/2), pt(3/4, 1/2), pt(3/4, 1/4)) && rightangle(pt(3/4, 1/2), pt(3/4, 1/4), pt(1/2, 1/4))'),
    'plane Euclidean geometry in Cartesian coordinates: Euclid\'s postulates, the parallel postulate, distances, right angles, parallels, midpoints, centroids and parallelograms; excludes the non-Euclidean geometries'))
# ---------------------------------------------------------------------------------------------------------------- hilbert
parts.append(theory('hilbert', ['euclid'], [], False, '', '',
    L('Hilbert, Grundlagen der Geometrie (the plane axioms, with the number of the axiom).  Group I, incidence:',
      'I.1 for two points A, B there is a line a that contains both',
      'I.2 for two different points A, B there is no more than one line that contains both',
      'I.3 a line contains at least two points; there are at least three points that are not on one line',
      'I.4-8 (space) three points not on a line lie in one plane; a line with two points in a plane lies in it; planes with a common point have a second one; there are four points not in one plane',
      'Group II, order (between):',
      'II.1 if B is between A and C, then A, B, C are three different points of a line, and B is between C and A',
      'II.2 for two points A, C there is a point B on the line AC such that C is between A and B',
      'II.3 of three points of a line no more than one is between the other two',
      'II.4 (Pasch) a line that meets a side of a triangle and misses its vertices meets another side',
      'Group III, congruence:',
      'III.1 a segment can be laid off on a given side of a given point of a line, in exactly one way up to congruence',
      'III.2 congruence of segments is transitive: if AB = CD and CD = EF then AB = EF (and reflexive and symmetric)',
      'III.3 if AB = A\'B\' and BC = B\'C\' for segments with B between A and C and B\' between A\' and C\', then AC = A\'C\'',
      'III.4 an angle can be laid off on a given side of a given ray, in exactly one way',
      'III.5 (SAS) if AB = A\'B\', AC = A\'C\' and the angles at A and A\' are equal, then the angles at B and B\' are equal',
      'Group IV, parallels: IV (Playfair) through a point outside a line there is no more than one line in the plane that does not meet it',
      'Group V, continuity: V.1 (Archimedes) laying off a segment AB again and again from A along a ray, one passes any point of the ray; V.2 (completeness) the points, lines and planes cannot be extended without violating the other axioms',
      'consequences used below: in the coordinate plane the axioms of groups I to IV hold with the reals as coordinates; groups I to III without IV give absolute (neutral) geometry, which euclid completes with IV and hyperbolic with its negation'),
    L('collinear(A, B, midpoint(A, B))', '¬collinear(pt(0, 0), pt(1, 0), pt(0, 1))', 'between(A, B, C) => collinear(A, B, C)', 'between(A, B, C) <=> between(C, B, A)', '¬between(A, A, C)', '¬between(A, B, A)',
      'dist2(A, B) > 0 => between(A, midpoint(A, B), B)', 'cong(A, B, A, B)', 'cong(A, B, B, A)', 'cong(A, B, C, D) <=> cong(C, D, A, B)', '(cong(A, B, C, D) && cong(C, D, E, F)) => cong(A, B, E, F)',
      'cong(A, B, C, D) => cong(B, A, C, D)', 'between(pt(0, 0), pt(1, 1), pt(2, 2))', '¬between(pt(0, 0), pt(2, 2), pt(1, 1))', 'between(pt(0, 0), pt(1, 0), pt(3, 0))'),
    'the 20 axioms of Hilbert\'s Grundlagen der Geometrie (incidence, order, congruence, parallels, continuity); the theorems checked here are the ones that hold in the coordinate model'))
# ---------------------------------------------------------------------------------------------------------------- hyperbolic and elliptic (Cayley-Klein models)
def curved(name, other, sign, word, trig, axioms, extra_theorems, doc):
    s = '-' if sign < 0 else '+'
    form = lambda a, b: f'(px({a}) * px({b}) + py({a}) * py({b}) {s} 1)'
    rules = L(f'{trig}(pt(a, b), pt(c, d)) ==> (1 {s.replace("-", "+") if False else ("-" if sign < 0 else "+")} (a * c + b * d))^2 / ((1 {"-" if sign < 0 else "+"} (a^2 + b^2)) * (1 {"-" if sign < 0 else "+"} (c^2 + d^2)))',
              f'cong(A, B, C, D) ==> {trig}(A, B) = {trig}(C, D)',
              f'rightangle(A, B, C) ==> {form("A","C")} * {form("B","B")} = {form("A","B")} * {form("B","C")}')
    sig = L(f'fn 0 {trig} {trig} C', 'fn 0 cong cong', 'fn 0 rightangle rightangle')
    common = ['cong(A, B, A, B)', 'cong(A, B, B, A)', 'cong(A, B, C, D) <=> cong(C, D, A, B)', '(cong(A, B, C, D) && cong(C, D, E, F)) => cong(A, B, E, F)', 'rightangle(A, B, C) <=> rightangle(C, B, A)']
    return theory(name, ['incidence'], other, False, sig, rules, axioms, L(*(common + extra_theorems)), doc)
hyp_ax = L('Hilbert groups I, II, III and V.1 hold (absolute geometry), and the parallel axiom is replaced by its negation: through a point outside a line there pass at least two lines that do not meet it (Bolyai, Lobachevsky)',
           'consequences (not decided here): the three angles of a triangle add up to less than two right angles; similar triangles are congruent; there are no rectangles; the area of a triangle is proportional to its angle defect',
           'the Beltrami-Klein model: the points are the points (x, y) with x^2 + y^2 < 1, the lines are the chords; the form <P, Q> = xP xQ + yP yQ - 1 gives the distance: cosh^2 d(P, Q) = <P, Q>^2 / (<P, P> <Q, Q>)',
           'collinearity is the usual one (cross(A, B, C) = 0); the angle at B between BA and BC is a right angle exactly when <A, C> <B, B> = <A, B> <B, C>; the Pythagorean theorem reads cosh c = cosh a cosh b',
           'coshsq(A, B) is cosh^2 of the distance, computed for points with known coordinates; cong(A, B, C, D) says that the two segments have the same one; rightangle(A, B, C) is the right angle at B')
ell_ax = L('Hilbert groups I and III hold in the form of the projective plane, there are no parallels: any two lines meet (Riemann); the order axioms hold only in a cyclic form (betweenness is replaced by separation)',
           'consequences (not decided here): the three angles of a triangle add up to more than two right angles; there are no parallel lines; two lines perpendicular to a third meet at a pole',
           'the model: the projective plane, or the sphere with antipodal points identified: the points are the points (x, y) of the chart, i.e. the vectors (x, y, 1); the form <P, Q> = xP xQ + yP yQ + 1 gives the distance: cos^2 d(P, Q) = <P, Q>^2 / (<P, P> <Q, Q>)',
           'collinearity is the usual one (cross(A, B, C) = 0); the angle at B between BA and BC is a right angle exactly when <A, C> <B, B> = <A, B> <B, C>; the Pythagorean theorem reads cos c = cos a cos b',
           'cossq(A, B) is cos^2 of the distance, computed for points with known coordinates; cong(A, B, C, D) says that the two segments have the same one; rightangle(A, B, C) is the right angle at B')
parts.append(curved('hyperbolic', ['euclid', 'elliptic'], -1, 'cosh', 'coshsq', hyp_ax,
    ['rightangle(pt(0, 0), pt(1/2, 0), pt(1/2, 1/3))', '¬rightangle(pt(0, 0), pt(1/2, 0), pt(1/3, 1/3))', 'coshsq(pt(0, 0), pt(1/2, 0)) = 4/3',
     'coshsq(pt(0, 0), pt(1/2, 1/3)) = coshsq(pt(0, 0), pt(1/2, 0)) * coshsq(pt(1/2, 0), pt(1/2, 1/3))', '¬rightangle(pt(3/4, 1/4), pt(1/2, 1/4), pt(1/2, 1/2))',
     '¬(rightangle(pt(3/4, 1/4), pt(1/2, 1/4), pt(1/2, 1/2)) && rightangle(pt(1/2, 1/4), pt(1/2, 1/2), pt(3/4, 1/2)) && rightangle(pt(1/2, 1/2), pt(3/4, 1/2), pt(3/4, 1/4)) && rightangle(pt(3/4, 1/2), pt(3/4, 1/4), pt(1/2, 1/4)))',
     'cong(pt(1/2, 0), pt(0, 0), pt(0, 0), pt(-1/2, 0))', 'cong(pt(1/2, 0), pt(0, 0), pt(0, 1/2), pt(0, 0))'],
    'hyperbolic geometry in the Beltrami-Klein model (the disc): the parallel postulate fails; excludes euclid and elliptic'))
parts.append(curved('elliptic', ['euclid', 'hyperbolic'], 1, 'cos', 'cossq', ell_ax,
    ['rightangle(pt(0, 0), pt(1/2, 0), pt(1/2, 1/3))', '¬rightangle(pt(0, 0), pt(1/2, 0), pt(1/3, 1/3))', 'cossq(pt(0, 0), pt(1, 0)) = 1/2', 'cossq(pt(0, 0), pt(1/2, 0)) = 4/5',
     'cossq(pt(0, 0), pt(1/2, 1/3)) = cossq(pt(0, 0), pt(1/2, 0)) * cossq(pt(1/2, 0), pt(1/2, 1/3))', '¬rightangle(pt(3/4, 1/4), pt(1/2, 1/4), pt(1/2, 1/2))',
     '¬(rightangle(pt(3/4, 1/4), pt(1/2, 1/4), pt(1/2, 1/2)) && rightangle(pt(1/2, 1/4), pt(1/2, 1/2), pt(3/4, 1/2)) && rightangle(pt(1/2, 1/2), pt(3/4, 1/2), pt(3/4, 1/4)) && rightangle(pt(3/4, 1/2), pt(3/4, 1/4), pt(1/2, 1/4)))',
     'cong(pt(1/2, 0), pt(0, 0), pt(0, 0), pt(-1/2, 0))', 'cong(pt(1/2, 0), pt(0, 0), pt(0, 1/2), pt(0, 0))'],
    'elliptic geometry in the projective-plane (spherical) model: there are no parallels; excludes euclid and hyperbolic'))
open('libsrc/th_geom.hum.imo', 'w', encoding='utf-8').write('\n'.join(parts) + '\n')
print('ok')
